// Função para calcular o tempo restante
function calcularTempoRestante(horario) {
  const agora = new Date();
  const [horaAlvo, minutoAlvo] = horario.split(':').map(Number);
  const dataAlvo = new Date(agora.getFullYear(), agora.getMonth(), agora.getDate(), horaAlvo, minutoAlvo);

  if (dataAlvo <= agora) {
    dataAlvo.setDate(dataAlvo.getDate() + 1); // Move para o próximo dia
  }

  const diferencaMs = dataAlvo - agora;
  const horasRestantes = Math.floor(diferencaMs / (1000 * 60 * 60));
  const minutosRestantes = Math.floor((diferencaMs % (1000 * 60 * 60)) / (1000 * 60));
  return { horasRestantes, minutosRestantes };
}

// Formatar horário no formato HH:MM
function formatarHorario(horario) {
  const [hora, minuto] = horario.split(':').map(Number);
  return `${hora.toString().padStart(2, '0')}:${minuto.toString().padStart(2, '0')}`;
}

const { horasRestantes, minutosRestantes } = calcularTempoRestante(horario);
const timeRemaining = `${horasRestantes} horas e ${minutosRestantes} minutos`;
