if (!q) return reply(`⏤͟͟͞͞⃝Cadê o *Usuário Da Pessoa* Que Você Deseja Stalkear?\nExemplo: ${prefix+command} @alok`)
try {//By: 𖧄 𝐋𝐔𝐂𝐀𝐒 𝐌𝐎𝐃 𝐃𝐎𝐌𝐈𝐍𝐀 𖧄
yoshino.sendMessage(from, { react: { text: `⬇️`, key: info.key }})
reply(`*_Fazendo download... Aguarde um momento_* 🚨`)
let response = await fetch(`${ZEROSITE}/api/dl/igstory?usuario=${q.replace("@", "")}&apikey=`+API_KEY_ZEROTWO)
let result = await response.json()
if (!result.resultado || result.resultado.length <= 0) {
return reply(`Não há storys disponíveis para este perfil, ou pode ser que a conta seja privada 🔒`)
}
let stories = result.resultado
for (let index = 0; index < stories.length; index++) {
let story = stories[index]
let caption = `Story ${index + 1} do perfil @${q.replace("@", "")}`
if (story.includes('.mp4')) {
await sleep(3000)
sendVideo(from, story, caption)
} else if (story.includes('.jpg') || story.includes('.png')) {
await sleep(1000)
sendImage(from, story, caption)
}
}
} catch (e) {
console.log(e)
return reply(`Não foi possível encontrar esse perfil no Instagram, ou pode ser que a API esteja fora do ar...`)
}
break

