if (budy.includes("clima")) {
  try {
    const clime = ["☁️", "⛅", "⛈️", "🌤️", "🌥️", "🌦️", "🌧️", "🌨️", "🌩️"];
    await reagir(from, clime[Math.floor(Math.random() * clime.length)]);
    
    const query = budy.replace("clima", "").trim();
    if (!query) return reply("Por favor, informe o nome da cidade. Exemplo: clima São Paulo");

    const formattedCity = query.normalize('NFD').replace(/[\u0300-\u036f]/g, "").toLowerCase().trim();
    const weatherData = await axios.get(`https://api.openweathermap.org/data/2.5/weather?q=${formattedCity}&appid=1d0bdf08a222f8f2da252ef8921ff4ab&units=metric&lang=pt_br`);

    const { name, main, weather } = weatherData.data;
    const { temp, temp_max, temp_min, humidity } = main;
    const description = weather[0].description;

    const now = moment.tz('America/Sao_Paulo');
    const date = now.format('DD/MM');
    const time = now.format('HH:mm');

    const climaResponse = `
🌪️ _CLIMA_ 🌪️
*📅 Data:* ${date}
*🌎 Cidade:* ${name}
*🌡️ Temperatura:* ${temp.toFixed()}ºC
*🔺 Temp. Max:* ${temp_max.toFixed()}ºC
*🔻 Temp. Min:* ${temp_min.toFixed()}ºC
*🌦️ Clima:* ${description}
*💧 Umidade:* ${humidity}%
〘 ${time}h 〙`;

    await yoshino.sendMessage(from, { text: climaResponse });

  } catch (error) {
    console.error(error);
    reply("Não foi possível obter as informações climáticas. Verifique o nome da cidade e tente novamente.");
  }
}

