if (budy2.toLowerCase().includes("pinterest")) {
  const query = budy2.replace(/pinterest/gi, '').trim();
  if (!query) return reply("Por favor, insira o nome do conteúdo que você deseja buscar no Pinterest.");

  const zerosited1 = "https://zero-two.online";
  await reagir(from, '🔍');

  try {
    const apiUrl = `${zerosited1}/api/search-pinterest?query=${encodeURIComponent(query)}&apikey=${API_KEY_ZEROTWO}`;
    const resultados = await fetchJson(apiUrl);
    console.log("Resposta da API recebida:", resultados);

    if (Array.isArray(resultados) && resultados.length > 0) {
      console.log(`Total de resultados encontrados: ${resultados.length}`);
      const resultadosAleatorios = resultados.sort(() => Math.random() - 0.5).slice(0, 8);
      const butao = [];

      resultadosAleatorios.forEach(item => {
        let videoUrl = item.link;
        if (item.quality === "4K" || item.quality === "Full HD") {
          videoUrl = item.hdLink || item.link;
        } else if (item.quality === "HD") {
          videoUrl = item.hdLink || item.link;
        }

        butao.push({
          video: { url: videoUrl },
          caption: `*❯❯ YOSHINO - PINTEREST ❮❮*\n\n*❒ Pesquisa:* ${query}\n🎥 *TÍTULO:* ${item.titulo}\n👤 *CRIADOR:* ${item.criador}`
        });
      });

      await yoshino.sendMessage(from, { video: { url: butao[0].video.url }, caption: butao[0].caption }, { quoted: selometa });
    } else {
      reply("Nenhum resultado encontrado para sua pesquisa.");
    }
  } catch (e) {
    reply("Erro ao buscar conteúdo no Pinterest. Tente novamente.");
  }
}


